const tid=$('Params').first().json['Table ID'];
const baseId=$('Params').first().json['Clayroots Base ID'];
const resp=$('Check Table').first().json||{};
const t=(resp.tables||[]).find(x=>x.id===tid);
if(!t){ throw new Error('Table '+tid+' not found in base '+baseId+'.'); }
const names=(t.fields||[]).map(f=>f.name);
if(!(names.includes('Email')||names.includes('public_emails_clean'))){ throw new Error('Table "'+t.name+'" has no Email or public_emails_clean field. Aborting.'); }
return [{ json:{ table:t.name, hasEmail:true, startedAt:new Date().toISOString() } }];

const MV=[{name:'ok',color:'greenBright'},{name:'catch_all',color:'yellowBright'},{name:'invalid',color:'redBright'},{name:'disposable',color:'orangeLight2'},{name:'unknown',color:'grayBright'},{name:'error',color:'orangeBright'},{name:'skipped',color:'grayLight2'}];
const BB=[{name:'verifying',color:'blueBright'},{name:'deliverable',color:'greenBright'},{name:'undeliverable',color:'redBright'},{name:'risky',color:'yellowBright'},{name:'unknown',color:'grayBright'},{name:'error',color:'orangeBright'},{name:'skipped',color:'grayLight2'}];
const SRC=[{name:'P0',color:'blueBright'},{name:'P1',color:'cyanBright'},{name:'P2',color:'tealBright'},{name:'P3',color:'purpleBright'},{name:'none',color:'grayBright'}];
const ST=[{name:'done',color:'greenBright'},{name:'verifying',color:'blueBright'},{name:'no_email_found',color:'redBright'},{name:'error',color:'orangeBright'}];
const sel=(name,choices)=>({name,type:'singleSelect',options:{choices}});
const txt=(name)=>({name,type:'singleLineText'});
// 2026-08-12 Operator ruling: the tier verdict lives in 'Email Source' (which waterfall tier found the
// email). 'Contact Source' (where the CONTACT came from) is owned by the builders. 'Source' is retired.
const defs=[ sel('MV P0',MV), txt('P1 (Trykitt)'), sel('MV P1',MV), txt('P2 (LeadMagic)'), sel('MV P2',MV), txt('P3 (Prospeo)'), sel('MV P3',MV), sel('BB',BB), txt('Final Email'), sel('Email Source',SRC), sel('Status',ST) ];
return defs.map(d=>({json:{def:d}}));

const row=$('Read Records').item.json; const f=row.fields||{};
const existing=((f.Email||(f.public_emails_clean||'').split(',')[0])||'').trim();
const G=(n)=>{ try{ const v=$(n).item.json; return (v&&typeof v==='object')?v:null; }catch(e){ return null; } };
const mv0=G('MV P0'),tk=G('Trykitt Find'),mv1=G('MV P1'),lm=G('LeadMagic Find'),mv2=G('MV P2'),pr=G('Prospeo Find'),mv3=G('MV P3');
const SK='skipped';
const body=(o)=>{ if(o&&typeof o.data==='string'){ try{ return JSON.parse(o.data); }catch(e){ return null; } } return o; };
const failed=(o)=>{ if(!o) return false; if(typeof o.data==='string') return true; if(o.error===true) return true; if(typeof o.error==='string'&&o.error!=='') return true; if(o.success===false) return true; if(Array.isArray(o.errors)&&o.errors.length) return true; if(o.code&&o.title&&o.detail) return true; const st=Number(o.status); if(Number.isFinite(st)&&(st<200||st>=300)) return true; if(Object.keys(o).length===0) return true; return false; };
const cause=(o)=>{ const b=body(o); if(!b) return 'unparseable_body'; const c=b.code||b.error_code||b.title||b.message||(typeof b.error==='string'?b.error:'')||('http_'+(b.status!==undefined?b.status:'unknown')); return String(c).slice(0,40); };
// A finder with no credits is not an error and never blocks a row. The tier records "no-credits",
// the run log flags it, and the waterfall carries on to the next provider.
const DRY=(o)=>{ if(!o||typeof o!=='object') return false; const b=body(o)||{}; const s=Number(b.status||b.statusCode||0); const t=(String(b.code||'')+' '+String(b.error_code||'')+' '+String(b.title||'')+' '+String(b.detail||'')+' '+String(b.message||'')+' '+(typeof b.error==='string'?b.error:'')).toLowerCase(); if(s===402) return true; return t.indexOf('insufficient_credit')>=0||t.indexOf('insufficient credit')>=0||t.indexOf('out of credits')>=0||t.indexOf('no credits')>=0; };
// MillionVerifier is the exception: it gates every tier, so without it nothing can resolve at all.
const MVDRY=(r)=>{ if(!r||typeof r!=='object') return false; const e=String(r.error||'').toLowerCase(); if(e.indexOf('insufficient credit')>=0||e.indexOf('no credit')>=0||e.indexOf('out of credit')>=0) return true; const c=Number(r.credits); return Number.isFinite(c)&&c<0; };
for(const p of [['MV P0',mv0],['MV P1',mv1],['MV P2',mv2],['MV P3',mv3]]){ if(MVDRY(p[1])){ throw new Error('MillionVerifier is out of credits ('+p[0]+', balance '+String((p[1]||{}).credits)+'). Nothing can be verified without it, so the run is stopping here. Top up and relaunch.'); } }
const tkDry=DRY(tk), lmDry=DRY(lm), prDry=DRY(pr);
const NEGATIVE=(o)=>{ const c=cause(o).toLowerCase(); return c.indexOf('no_match')>=0||c.indexOf('not_found')>=0||c.indexOf('no-results-found')>=0||c.indexOf('no results')>=0||c.indexOf('find a verified email')>=0||c.indexOf("couldn't find")>=0||c.indexOf('could not find')>=0||c.indexOf('unable to verify email')>=0; };
const tkFail=tk?(failed(tk)||!tk.jobId||typeof tk.email!=='string'):false;
const lmFail=lm?failed(lm):false;
const prFail=pr?failed(pr):false;
const lmNeg=lmFail&&NEGATIVE(lm);
const prNeg=prFail&&NEGATIVE(pr);
// out of credits never counts as a hard failure, so it can never make the row an error
const lmHard=lmFail&&!lmNeg&&!lmDry;
const prHard=prFail&&!prNeg&&!prDry;
const tkE=(tk&&!tkFail)?((tk.email&&tk.email!=='no-results-found')?tk.email:''):'';
const lmE=(lm&&!lmFail)?(lm.email||''):'';
const prPick=(o)=>{ const e=o&&o.person&&o.person.email; return (e&&e.revealed===true&&e.email&&e.email.indexOf('*')===-1)?e.email:''; };
const prE=(pr&&!prFail)?prPick(pr):'';
const answered=(!!tk&&!tkFail)||(!!lm&&!lmFail)||lmNeg||(!!pr&&!prFail)||prNeg;
const MVOK=['ok','catch_all','invalid','disposable','unknown'];
const mvVal=(r)=> r?(MVOK.includes(r.result)?r.result:'error'):SK;
const mvErr=(r)=> r&&(r.resultcode===4||(r.error&&r.error!=='')||!MVOK.includes(r.result));
const IND=(r)=> r==='catch_all'||r==='unknown';
let final='',source='none',bb='skipped',pe='',ps='',resolved=false,verifying=false,errored=false;
if(existing&&mv0){ if(mv0.result==='ok'){final=existing;source='P0';resolved=true;} else if(IND(mv0.result)){verifying=true;bb='verifying';pe=existing;ps='P0';} else if(mvErr(mv0)){errored=true;} }
if(!resolved&&!verifying&&tkE&&mv1){ if(mv1.result==='ok'){final=tkE;source='P1';resolved=true;} else if(IND(mv1.result)){verifying=true;bb='verifying';pe=tkE;ps='P1';} else if(mvErr(mv1)){errored=true;} }
if(!resolved&&!verifying&&lmE&&mv2){ if(mv2.result==='ok'){final=lmE;source='P2';resolved=true;} else if(IND(mv2.result)){verifying=true;bb='verifying';pe=lmE;ps='P2';} else if(mvErr(mv2)){errored=true;} }
if(!resolved&&!verifying&&prE&&mv3){ if(mv3.result==='ok'){final=prE;source='P3';resolved=true;} else if(IND(mv3.result)){verifying=true;bb='verifying';pe=prE;ps='P3';} else if(mvErr(mv3)){errored=true;} }
const finderFail=(lmHard||prHard)&&!answered;
const status= resolved?'done':(verifying?'verifying':((errored||finderFail)?'error':'no_email_found'));
const causes=[];
if(tkDry)causes.push('P1:no-credits');
if(lmDry)causes.push('P2:no-credits'); else if(lmHard)causes.push('P2:'+cause(lm));
if(prDry)causes.push('P3:no-credits'); else if(prHard)causes.push('P3:'+cause(pr));
const tkCell = tk?(tkDry?'no-credits':(tkFail?'no-results-found':(tk.email||'no-results-found'))):SK;
const lmCell = lm?(lmDry?'no-credits':(lmFail?(lmHard?'error':'no-results-found'):(lmE||'no-results-found'))):SK;
const prCell = pr?(prDry?'no-credits':(prFail?(prHard?'error':'no-results-found'):(prE||'no-results-found'))):SK;
return { json:{ id:row.id, 'MV P0': existing?mvVal(mv0):SK, 'P1 (Trykitt)': tkCell, 'MV P1': tkE?mvVal(mv1):SK, 'P2 (LeadMagic)': lmCell, 'MV P2': lmE?mvVal(mv2):SK, 'P3 (Prospeo)': prCell, 'MV P3': prE?mvVal(mv3):SK, 'BB':bb, 'Final Email':final, 'Email Source':source, 'Status':status, _pendEmail:pe, _pendSlot:ps, _errP1:tkDry?1:0, _errP2:(lmHard||lmDry)?1:0, _errP3:(prHard||prDry)?1:0, _failCauses:causes.join('|') } };

const sd=$getWorkflowStaticData('global');
let eid=String($execution.id); try{ eid=String($('Read Records').first().json._execId||eid); }catch(e){}
if(!sd._wfFinderFails||sd._wfFinderFails.execId!==eid){ sd._wfFinderFails={execId:eid,p1:0,p2:0,p3:0,causes:{}}; }
const a=sd._wfFinderFails;
return $input.all().map(i=>{ const j={...i.json};
 if(j._errP1) a.p1++;
 if(j._errP2) a.p2++;
 if(j._errP3) a.p3++;
 if(j._failCauses){ for(const c of String(j._failCauses).split('|')){ if(c) a.causes[c]=(a.causes[c]||0)+1; } }
 for(const k of Object.keys(j)){ if(k.charAt(0)==='_') delete j[k]; }
 return {json:j}; });

const wfid='iNzuePWU2UoByJ7U';
let r=null;
try{ r=$('Read Records').first().json; }catch(e){ r=null; }
if(!r||!r._execId){ let p={}; try{ p=$('Params').first().json||{}; }catch(e){}
  let st=''; try{ st=$('Email Guard').first().json.startedAt||''; }catch(e){}
  r={ _execId:String($execution.id), _tableId:p['Table ID']||'', _view:p['View']||'', _startedAt:st||new Date().toISOString(), _trigger:'form', _total:0, _clientId:'' }; }
const eid=String(r._execId);
const start=r._startedAt||new Date().toISOString();
const recIn=Number(r._total)||0;

// Prior totals come from the run's own Hub row, not from static data.
// Static data written inside a sub-execution is not persisted back; the row is.
const BLANK={resolved:0,verifying:0,noEmail:0,errored:0,p0:0,p1:0,p2:0,p3:0,ffP2:0,ffP3:0,causes:{}};
let a=Object.assign({},BLANK);
try{
  const prior=$('Read Log Row').first().json;
  const raw=prior&&prior.fields?prior.fields.Tally:null;
  if(raw){ const parsed=JSON.parse(String(raw)); if(parsed&&String(parsed.execId)===eid){ a=Object.assign({},BLANK,parsed); a.causes=parsed.causes||{}; } }
}catch(e){ a=Object.assign({},BLANK); }

let rows=[]; try{ rows=$('To Airtable').all().map(i=>i.json); }catch(e){}
const c=(f)=>rows.filter(f).length;
a.resolved+=c(x=>x.Status==='done');
a.verifying+=c(x=>x.Status==='verifying');
a.noEmail+=c(x=>x.Status==='no_email_found');
a.errored+=c(x=>x.Status==='error');
a.p0+=c(x=>x.Status==='done'&&x.Source==='P0');
a.p1+=c(x=>x.Status==='done'&&x.Source==='P1');
a.p2+=c(x=>x.Status==='done'&&x.Source==='P2');
a.p3+=c(x=>x.Status==='done'&&x.Source==='P3');

// This batch's finder refusals, taken from the in-memory counter which IS reliable within one execution.
try{
  const sd=$getWorkflowStaticData('global');
  const ff=sd._wfFinderFails;
  if(ff&&String(ff.execId)===String($execution.id)){
    a.ffP2+=(ff.p2||0); a.ffP3+=(ff.p3||0);
    for(const k of Object.keys(ff.causes||{})){ a.causes[k]=(a.causes[k]||0)+ff.causes[k]; }
    ff.p1=0; ff.p2=0; ff.p3=0; ff.causes={};
  }
}catch(e){}

a.execId=eid;
const ffTotal=a.ffP2+a.ffP3;
const topCause=(tier)=>{ const m=a.causes||{}; let best='',n=0; for(const k of Object.keys(m)){ if(k.indexOf(tier+':')===0&&m[k]>n){ n=m[k]; best=k.slice(tier.length+1); } } return best; };
const ffLine=(tier,label,n)=>{ const tc=n?topCause(tier):''; return '- **'+tier+' '+label+':** '+n+' call'+(n===1?'':'s')+' failed'+(tc?' ('+tc+')':''); };
const recordsOut=a.resolved+a.verifying;
const accounted=a.resolved+a.verifying+a.noEmail+a.errored;
const isFinal=recIn===0 || accounted>=recIn;
const ms=Date.parse(start);
const dur=ms?Math.round((Date.now()-ms)/1000):null;
const trig=r._trigger||'form';
const viewTxt=r._view?(' · view: '+r._view):'';
const desc=[
'**'+recIn+' read, '+a.resolved+' resolved, '+a.verifying+' verifying, '+a.errored+' errored**'+(ffTotal?' · '+ffTotal+' finder calls refused':''),
'',
'**Launch:** '+trig+'-launched · batched 100/sub-execution'+viewTxt+' · find + verify (MV P0 / Trykitt / LeadMagic / Prospeo / BounceBan)',
'',
'**Progress:** '+accounted+' of '+recIn+' accounted',
'',
'**Results**',
'- **Resolved (Status=done):** '+a.resolved+' · P0 existing '+a.p0+' · P1 Trykitt '+a.p1+' · P2 LeadMagic '+a.p2+' · P3 Prospeo '+a.p3,
'- **Handed to BounceBan (pending async verdicts):** '+a.verifying,
'- **No email found (finder answered, nothing there):** '+a.noEmail,
'- **Errored (never actually looked up, retryable):** '+a.errored,
'- **Rows written (resolved+verifying):** '+recordsOut
].concat(ffTotal?['','**Finder failures (the API refused the call, not a negative)**',ffLine('P2','LeadMagic',a.ffP2),ffLine('P3','Prospeo',a.ffP3)]:[]).concat(['','**Duration:** '+(dur!=null?dur+'s':'n/a')]).join('\n');
return [{ json:{ 'Automation':'Waterfall Emails', 'Run at': start, 'Target': r._tableId, 'View': r._view||'', 'Records In': recIn, 'Records Out': recordsOut, 'Execution ID': eid, 'Execution Link': 'https://n8n.flowroots.com/workflow/'+wfid+'/executions/'+eid, 'Status': isFinal?((a.errored||ffTotal)?'Succeeded with errors':'Succeeded'):'Running', 'Trigger': trig, 'Errors': a.errored, 'Duration s': dur, 'Tally': JSON.stringify(a), 'Description': desc } }];

const j=Object.assign({},$json);
let rec=[];
try{ const cid=$('Read Records').first().json._clientId; if(cid) rec=[cid]; }catch(e){}
if(rec.length){ j['Client']=rec; } else { delete j['Client']; }
return {json:j};

const rec=$('Fetch Launch Record').first().json;
const f=rec.fields||{};
const client=$('Resolve Base').first().json;
const cf=client.fields||{};
return [{ json: {
  'Clayroots Base ID': ((cf['Clayroots Base ID']||'')+'').trim(),
  'Table ID': ((f['Table ID']||'')+'').trim(),
  'Max Rows': f['Max Rows'] || 0,
  'View': ((f['View']||'')+'').trim(),
  '_launchRecordId': rec.id,
  'submittedAt': new Date().toISOString()
} }];

const p=$('Params').first().json;
let started=''; try{ started=$('Email Guard').first().json.startedAt||''; }catch(e){}
let cid=''; try{ cid=p.clientRecordId||''; }catch(e){}
if(!cid){ try{ const rc=$('Resolve Client').first().json; if(rc&&rc.id) cid=rc.id; }catch(e){} }
let trig='form';
if(!p._launchRecordId){ try{ if($('Record Webhook').first().json) trig='webhook'; }catch(e){} }
let total=0; try{ total=$('Fetch Rows').all().filter(i=>i.json&&i.json.id).length; }catch(e){}
const cap=Number(p['Max Rows'])||100000;
const ctx={ _baseId:p['Clayroots Base ID'], _tableId:p['Table ID'], _view:String(p['View']||''), _execId:String($execution.id), _startedAt:started||new Date().toISOString(), _clientId:cid, _trigger:trig, _total:Math.min(total,cap) };
return $input.all().map(i=>({ json:Object.assign({},i.json,ctx) }));
